   'complete-visit':async b=>{const f=b.closest('[data-note-form]');await BookItReview.saveDraft(f,true);const payload={status:'completed',note:f.querySelector('.note-body').value,scope:f.querySelector('input[type=radio]:checked').value==='yes',scope_detail:f.querySelector('.note-scope-detail').value};if(f.querySelector('.note-active'))Object.assign(payload,{active_hours:f.querySelector('.note-active').value,active_note:f.querySelector('.note-active-note').value,active_periods:window.CareSleepoverSupport?.read(f)||[]});Object.assign(payload,{km:f.querySelector('.note-km').value,km_from:f.querySelector('.note-km-from').value,km_to:f.querySelector('.note-km-to').value});const result=await call('/bookings/'+b.dataset.id,payload,'PATCH');BookItReview.finishDraft(f);toast(result.billing_notice||(result.billing_status==='issued'?'Shift completed. The invoice is ready and its email is queued.':result.billing_status==='not-claimable'?'Shift completed. This introductory visit is not invoiced.':'Shift completed. Invoice processing is queued; the participant can review the shift.'));await render();},
