   'accept-series':async b=>{const f=el('flowSeries'),ids=[...f.querySelectorAll('[name=visit]:checked')].map(x=>Number(x.value));if(!ids.length)throw Error('Choose the visits you can work.');if(seriesData.plan_id&&!f.querySelector('[name=read]').checked)throw Error('Read and confirm this plan version.');await call('/journey/series/'+b.dataset.id+'/accept',{ids,revisions:Object.fromEntries(seriesData.visits.map(v=>[v.id,v.revision])),plan_ack:!!seriesData.plan_id,plan_id:seriesData.plan_id,plan_version:seriesData.plan_version});toast(ids.length+' visits accepted.');location.hash='#/journey';},
