   'create-calendar':async()=>{if(!await dialog('Share visit times with your calendar?','<p>Your calendar service will receive generic visit times. Keep this subscription link private.</p>','Create link'))return;const d=await call('/journey/calendar',{confirm:true});el('flowCalendarLink').innerHTML=`<p>Copy this secret URL into your calendar’s “Subscribe from URL” option.</p><label class="flow-field">Private subscription URL<input readonly value="${e(d.url)}" aria-label="Private calendar subscription URL"></label><p>Expires ${e(fmtAU(d.expires_at.slice(0,10)))}.</p>`;},
