   'test-email':async b=>{const context=snapshot(),out=b.closest('.flow-email-test')?.querySelector('[data-email-test-status]');if(out)out.textContent='Queuing your test email…';try{const r=await API.call('/email-test',{method:'POST',body:{},noFor:true});if(context!==snapshot())return;if(r.ok===false)throw Error(r.error||r.message||'The test email could not be queued.');if(r.status!=='queued')throw Error('The server did not confirm that the test was queued. Refresh this website and try again.');const msg=`Test email queued for ${r.queued_to||API.me.email}${r.delivery_id?' (message #'+r.delivery_id+')':''}. Use Check test status, then look in your inbox and junk folder.`;if(out)out.textContent=msg;const check=b.closest('.flow-email-test')?.querySelector('[data-flow-action=check-email-test]');if(check&&r.delivery_id){check.dataset.id=String(r.delivery_id);check.hidden=false;}toast(msg);}catch(err){if(context===snapshot()&&out)out.textContent=err.message;throw err;}},
